#include <stdio.h>
#include <math.h>

int main() {
    double a, b, c;

    printf("请输入第一条直角边的长度: ");
    scanf("%lf", &a);
    printf("请输入第二条直角边的长度: ");
    scanf("%lf", &b);

    c = sqrt(a * a + b * b);

    printf("最长边（斜边）的长度为: %.2f\n", c);

    return 0;
}
